{
  "findings": [
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "A parent reports that Microsoft may share collected data with third‑party ad companies such as Facebook, Media.net, Outbrain, Taboola and Yahoo.",
      "stance": "risk",
      "quote": "Advertisers sometimes include their own or other advertising partners’ web beacons within their ads that we display, enabling them to set and read their own cookies. In some cases, we share reports with advertisers about the data we have collected on their sites or ads. Additionally, Microsoft partners with Xandr (a Microsoft Company) and third-party ad companies to help provide some of our advertising services, and we also allow other third-party ad companies to display advertisements on our sites. These third parties may place cookies on your devices and collect data about your online activities across websites or online services. These companies currently include, but are not limited to: [Facebook](https://www.facebook.com/help/568137493302217), [Media.net](https://www.media.net/adchoices), [Outbrain](https://my.outbrain.com/recommendations-settings/home), [Taboola](https://www.taboola.com/privacy-policy) and [Yahoo](https://legal.yahoo.com/xw/en/yahoo/privacy/intl/index.html)."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "A parent reports that Microsoft may retain diagnostic data for troubleshooting and product improvement.",
      "stance": "neutral",
      "quote": "Many Microsoft products collect diagnostic data to keep our services secure and up‑to‑date; help ensure they work as expected; detect, diagnose, and fix problems; and improve our products."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "A parent reports that users can control optional diagnostic data and delete some data via the Microsoft Privacy Dashboard.",
      "stance": "mitigation",
      "quote": "You can control whether to send us optional diagnostic data. ... You can manage your prompt history in product and on the Microsoft Privacy Dashboard, and can adjust your location, language, and other additional privacy settings in product."
    },
    {
      "ref": "[D527]",
      "area": "age_gating",
      "claim": "A parent reports that the app does not have an age gate; it is not designed specifically for children.",
      "stance": "neutral",
      "quote": "The Microsoft Copilot [website](https://copilot.microsoft.com/) and app (on Windows, Mac, iOS, and Android) are the core of the consumer Copilot experience, where you can search the web, create content, and interact with features like Copilot Vision, as well as let Microsoft Copilot interact with other apps, services, and websites to take actions on your behalf."
    },
    {
      "ref": "[D527]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with a child only if the child initiates contact within the app, and this feature can be turned off.",
      "stance": "mitigation",
      "quote": "When you use Microsoft Copilot, it will use your prompts, location, language, and related settings to provide helpful responses and improve services. ... Microsoft Copilot also appears in other Microsoft products like Microsoft Edge and XBOX. In these cases, data is generally used according to each product’s primary uses."
    }
  ]
}
